    entities = state.get(collection, {})
    if not isinstance(entities, dict):
        return findings
    allowed = params.get("allowed_values", [])
    for position, call in enumerate(trace):
        if not isinstance(call, dict):
            continue
        if call.get("name") != params.get("action", ""):
            continue
        args = call.get("args", {})
        if not isinstance(args, dict):
            continue
        entity_id = args.get(params.get("key_arg", ""))
        entity = entities.get(entity_id)
        if not isinstance(entity, dict):
            continue
        value = entity.get(params.get("entity_field", ""))
        if value in allowed:
            continue
        trace_index = position
        stored_index = call.get("index")
        if isinstance(stored_index, int) and not isinstance(stored_index, bool):
            trace_index = stored_index
        findings.append({"trace_index": trace_index, "detail": "Forbidden action " + str(params.get("action", "")) + " for " + str(entity_id) + ": " + str(params.get("entity_field", "")) + "=" + str(value) + " is not in allowed values " + str(allowed) + "."})
    return findings
